import{_ as e,o as t,c as o,a3 as a}from"./chunks/framework.Dq9u6otn.js";const p=JSON.parse('{"title":"AI 助手支持","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/ai.md","filePath":"advanced/ai.md"}'),r={name:"advanced/ai.md"};function s(d,l,i,c,n,h){return t(),o("div",null,[...l[0]||(l[0]=[a(`<h1 id="ai-助手支持" tabindex="-1">AI 助手支持 <a class="header-anchor" href="#ai-助手支持" aria-label="Permalink to &quot;AI 助手支持&quot;">​</a></h1><p>coolui-scroller 为 AI 编码助手（Cursor / Claude Code / CodeBuddy / Trae / GitHub Copilot 等）准备了可直接读取的文档：<strong>装包即用，不需要额外配置</strong>，AI 就能准确写出组件代码。</p><h2 id="提供了什么" tabindex="-1">提供了什么 <a class="header-anchor" href="#提供了什么" aria-label="Permalink to &quot;提供了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>位置</th><th>内容</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>随 npm 包发布，<code>node_modules/coolui-scroller/AGENTS.md</code></td><td>组件心智模型、最小可用示例、事件与属性对照、高频坑</td></tr><tr><td><code>llms.txt</code></td><td>随 npm 包发布，<code>node_modules/coolui-scroller/llms.txt</code></td><td>该包的文档索引与「关键事实」清单</td></tr><tr><td><code>llms-full.txt</code></td><td>线上（内容最全）</td><td>全部组件 API 与示例合并成的单文件全文</td></tr></tbody></table><p>线上地址（也可直接发给 AI）：</p><ul><li>索引：<a href="https://wzs28150.github.io/coolui-scroller/v4/llms.txt" target="_blank" rel="noreferrer">https://wzs28150.github.io/coolui-scroller/v4/llms.txt</a></li><li>全文：<a href="https://wzs28150.github.io/coolui-scroller/v4/llms-full.txt" target="_blank" rel="noreferrer">https://wzs28150.github.io/coolui-scroller/v4/llms-full.txt</a></li></ul><blockquote><p>uni-app 版把包名换成 <code>coolui-scroller-uni</code> 即可，文件结构完全一致。</p></blockquote><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><h3 id="_1-直接让-ai-读-最快" tabindex="-1">1. 直接让 AI 读（最快） <a class="header-anchor" href="#_1-直接让-ai-读-最快" aria-label="Permalink to &quot;1. 直接让 AI 读（最快）&quot;">​</a></h3><p>在 AI 助手里说：</p><blockquote><p>先读 <a href="https://wzs28150.github.io/coolui-scroller/v4/llms-full.txt%EF%BC%8C%E5%86%8D%E7%94%A8" target="_blank" rel="noreferrer">https://wzs28150.github.io/coolui-scroller/v4/llms-full.txt，再用</a> coolui-scroller 写一个下拉刷新 + 上拉加载的列表页</p></blockquote><h3 id="_2-让-ai-自动找到-推荐" tabindex="-1">2. 让 AI 自动找到（推荐） <a class="header-anchor" href="#_2-让-ai-自动找到-推荐" aria-label="Permalink to &quot;2. 让 AI 自动找到（推荐）&quot;">​</a></h3><p>把下面这段放进你项目的 <code>AGENTS.md</code>（Cursor 可放 <code>.cursor/rules/*.mdc</code>，CodeBuddy / Claude Code 放对应的 Rules）：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## coolui-scroller</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用 coolui-scroller 组件前，先读 node_modules/coolui-scroller/AGENTS.md；</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">需要完整组件 API 与示例时，读 https://wzs28150.github.io/coolui-scroller/v4/llms-full.txt</span></span></code></pre></div><p>这样每次让 AI 改列表页时，它都会先拿到正确的属性、事件与插槽写法，不用你反复贴文档。</p><h3 id="_3-配合编辑器插件" tabindex="-1">3. 配合编辑器插件 <a class="header-anchor" href="#_3-配合编辑器插件" aria-label="Permalink to &quot;3. 配合编辑器插件&quot;">​</a></h3><p>安装<a href="/coolui-scroller/v4/advanced/plugin.html">编辑器插件</a>后，写 <code>.wxml</code> / <code>.vue</code> 时标签、属性、事件、插槽都有补全与中文悬停文档，和 AI 补全互补。</p><h2 id="这样设计的原因" tabindex="-1">这样设计的原因 <a class="header-anchor" href="#这样设计的原因" aria-label="Permalink to &quot;这样设计的原因&quot;">​</a></h2><ul><li><strong>文件名是通用约定</strong>：<code>AGENTS.md</code> 是 AI 编码助手的默认入口文件，<code>llms.txt</code> / <code>llms-full.txt</code> 遵循 <a href="https://llmstxt.org/" target="_blank" rel="noreferrer">llms.txt 约定</a>，主流工具会优先探测。</li><li><strong>随包发布</strong>：AI 在 <code>node_modules</code> 里就能读到，不依赖联网；同时线上留一份全量单文件，避免把 npm 包撑大。</li><li><strong>自动生成</strong>：内容由 <code>scripts/build-llms.mjs</code> 从 <code>doc/</code> 下的文档生成，组件文档一改，AI 看到的就同步更新（执行 <code>pnpm docs:llms</code>）。</li></ul><blockquote><p>如果你发现 AI 写出的组件用法不对，多半是它没读到上面的文件 —— 用「第 2 步」的规则片段把它指过去即可，也欢迎到 <a href="/coolui-scroller/v4/community.html">社群</a>反馈。</p></blockquote>`,20)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
